/bin/bash -c "python3 - <<'PY'
import math

def mm(a,b):
    return [[sum(x*y for x,y in zip(row,col)) for col in zip(*b)] for row in a]
def ent(row): return -sum(p*math.log(p) for p in row if p>0)
for name,p,pi in [('positive spectrum',[[.9,.1],[.2,.8]],[2/3,1/3]),('short example',[[.5,.5],[1.,0.]],[2/3,1/3])]:
    print(name,'P=',p, 'H_infinity=',2*ent(pi))
    q=[[1.,0.],[0.,1.]]
    for t in range(1,13):
        q=mm(q,p)
        print(t,format(sum(ent(row) for row in q),'.12f'))
PY"
